const fs=require('fs');
const key=JSON.parse(fs.readFileSync('C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/deepseek-key.json','utf8')).apiKey;
async function ds(sys, user, maxTok){
  const resp = await this.helpers.httpRequest({method:'POST', url:'https://api.deepseek.com/chat/completions',
    headers:{Authorization:'Bearer '+key, 'Content-Type':'application/json'}, timeout:120000,
    body:{model:'deepseek-chat', messages:[{role:'system', content:sys},{role:'user', content:user}],
      response_format:{type:'json_object'}, temperature:0.7, max_tokens:maxTok||800}, json:true});
  return resp.choices[0].message.content;
}
const channelName=$json.channelName;
const sys='You are a scriptwriter for short-form vertical video content (YouTube Shorts / Reels / TikTok).
Write a punchy 60-second voiceover script based on the title and summary below, plus a title and a footage search keyword for the finished video.

TASK
Produce three things from the input above:
1. A short, scroll-stopping title for the video.
2. A single spoken-word script meant to be read aloud in under 60 seconds.
3. A keyword to search stock footage that visually matches the script.

HARD RULES — SCRIPT
- The first three words must hook the listener: a surprising fact, a bold claim, a question, or a direct command. Never open with "Imagine", "In a world", "Did you know", or any generic intro.
- Maximum 150 words total, including the closing line.
- Plain spoken text only. No stage directions, no parentheses, no brackets, no camera or visual cues, no emojis, no hashtags, no labels like "Voiceover:" or "Scene:".
- No filler words (basically, actually, just, really, very, kind of, sort of, etc.).
- Short, punchy sentences. Vary rhythm: mix very short fragments with slightly longer lines.
- Tone: confident and direct, matched to the subject in the summary — serious for serious topics, energetic for lighter ones.
- End with exactly this line, replacing the placeholder with the channel name above: Follow CHANNELNAME for more

HARD RULES — TITLE
- Maximum 60 characters.
- No clickbait that misrepresents the content. No emojis, no hashtags, no quotation marks.
- Must reflect the actual content of the script, not just the input title.

HARD RULES — KEYWORD
- 1 to 4 words describing a concrete, filmable visual (an object, a place, an action, a scene) that matches the mood and topic of the script.
- No abstract concepts (e.g. not "innovation" or "freedom") — only things a stock footage search can return real clips for (e.g. "city traffic at night", "hands typing keyboard").
- English only, regardless of the input language, since stock libraries are indexed in English.

BEFORE YOU ANSWER
Count the words in the script. If over 150, cut whole sentences — never compress ideas into broken grammar.

OUTPUT FORMAT
Return ONLY a single JSON object with exactly these keys: {"title": string, "script": string, "keyword": string}'.replace('CHANNELNAME', channelName);
const user='Summary: '+$json.summary+'
Channel: '+channelName;
const raw=await ds(sys, user, 900);
let out=null, parseErr=null;
try{ out=JSON.parse(raw); }catch(e){ parseErr=String(e); }
if(!out) throw new Error('DeepSeek 未返回可解析 JSON: '+parseErr+' | raw='+String(raw).slice(0,200));
return [{json:{...$json, raw, output:{title:out.title, script:out.script, keyword:out.keyword}}}];

const fs=require('fs'); const cp=require('child_process');
const dir='C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/16419-c-data'; fs.mkdirSync(dir,{recursive:true});
const kw=$json.keyword;
// ① 模板原节点：Pexels API 无 key 的真实行为（凭证缺口实证）
let pexelsStatus=0, pexelsBody='';
try{ await this.helpers.httpRequest({method:'GET', url:'https://api.pexels.com/videos/search?query='+encodeURIComponent(kw)+'&min_duration=55&max_duration=65&orientation=portrait&per_page=1', timeout:30000, json:true}); pexelsStatus=200; }
catch(e){ const m=/status code (\d{3})/.exec(String(e.message)); pexelsStatus=(e.response&&(e.response.status||e.response.statusCode)) || e.httpCode || e.statusCode || (m?parseInt(m[1]):0); pexelsBody=String(e.message).slice(0,200); }
// ② 免 key 公开素材库（Mixkit vertical 列表页，真搜索真下载）
const listUrl='https://mixkit.co/free-stock-video/vertical/';
const html=await this.helpers.httpRequest({method:'GET', url:listUrl, timeout:60000});
const found=[...String(html).matchAll(/https:\/\/assets\.mixkit\.co\/videos\/(\d+)\/\1-360\.mp4/g)].map(m=>m[1]);
const uniq=[...new Set(found)].slice(0,8);
// ③ 文件级竖屏校验（模板缺的那一步：orientation 只在搜索级生效）
function dims(u){ try{ const o=cp.execSync('ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "'+u+'"',{timeout:60000}).toString().trim().split(','); return {w:parseInt(o[0]),h:parseInt(o[1])}; }catch(e){ return null; } }
let pick=null, probed=[];
for(const id of uniq){ const u='https://assets.mixkit.co/videos/'+id+'/'+id+'-720.mp4'; const d=dims(u); probed.push({id, u, d}); if(d && d.h>d.w){ pick={id,u,d}; break; } }
if(!pick) throw new Error('免 key 素材源未找到竖屏文件，probed='+JSON.stringify(probed));
const footage=dir+'/footage.mp4';
cp.execSync('curl.exe -s -L -o "'+footage+'" "'+pick.u+'"',{timeout:180000});
const size=fs.statSync(footage).size;
return [{json:{...$json, pexelsStatus, pexelsBody, footage, footageSize:size, footageW:pick.d.w, footageH:pick.d.h, footageId:pick.id, source:'mixkit.co/free-stock-video/vertical', candidates:uniq.length}}];

