const fs=require('fs'); const R=[];
function T(n,c){R.push((c?'PASS':'FAIL')+' | '+n);}
const S=String($json.script||''), TT=String($json.title||''), KW=String($json.keyword||'');
// ---- 链路完整性（硬闸门）----
T('DeepSeek 真调返回三字段齐(结构闸门)', S.length>20 && TT.length>0 && KW.length>0);
T('Pexels 无 key 真实 401（凭证缺口实证）', $json.pexelsStatus===401);
T('免 key 素材源真返回候选列表(>=3)', $json.candidates>=3);
T('素材真下载且>200KB', $json.footageSize>200000);
T('素材文件级竖屏校验 h>w（模板缺的这一步）', $json.footageH>$json.footageW);
T('edge-tts 真出音频 >20KB', $json.audioSize>20000);
T('音频时长 >5s', $json.audioSec>5);
T('成片存在 >500KB', $json.videoSize>500000);
T('成片竖屏 1080x1920（Shorts 规格）', $json.outW===1080 && $json.outH===1920);
T('成片时长≈音频(±2s)', Math.abs($json.outSec-$json.audioSec)<2);
T('成片 h264 视频流', $json.vcodec==='h264');
T('成片 aac 音频流', $json.acodec==='aac');
T('台账落盘且 STATUS=DONE', $json.ledgerRows>=1 && $json.ledgerRow.STATUS==='DONE');
T('台账可持久化重读', JSON.parse(fs.readFileSync('C:/Users/Administrator/.easyclaw/workspace/n8n-lesson-crew/state/16419-c-data/ledger.json','utf8')).length>=1);
T('YouTube 发布为 mock（未真发）', $json.publish.mode==='mock');
T('单条口播 ≤60s 成片时长为 55-65s 窗内素材量级', $json.outSec>5 && $json.outSec<=62);
// ---- 模型合规观测（模板硬规则，非闸门，供教案记录）----
const obs=[];
obs.push({rule:'script 词数 ≤150', got:$json.words, ok:$json.words<=150});
obs.push({rule:'title ≤60 字符', got:TT.length, ok:TT.length<=60});
obs.push({rule:'keyword 1-4 词且纯 ASCII 英文', got:KW, ok:(KW.trim().split(/\s+/).length<=4 && KW.trim().split(/\s+/).length>=1 && /^[\x20-\x7E]+$/.test(KW))});
obs.push({rule:'结尾句 = Follow '+$json.channelName+' for more', got:S.slice(-60), ok:new RegExp('Follow '+$json.channelName+' for more[.!]?$').test(S.trim())});
obs.push({rule:'无 emoji / hashtag', got:(/#/.test(S)||/[\u{1F300}-\u{1FAFF}]/u.test(S))?'含':'无', ok:!(/#/.test(S)||/[\u{1F300}-\u{1FAFF}]/u.test(S))});
obs.push({rule:'首三词非被禁开场(Imagine/In a world/Did you know)', got:S.split(/\s+/).slice(0,3).join(' '), ok:!/^(Imagine|In a world|Did you know)/i.test(S.trim())});
const fails=R.filter(x=>x.indexOf('FAIL')===0);
console.log('==== L2-C 16419 ====');
console.log(JSON.stringify({total:R.length, pass:R.length-fails.length, fail:fails.length, fails, obs}, null, 1));
if(fails.length) throw new Error('L2C FAIL: '+fails.join(' ; '));
return [{json:{assertions:R, obs, outSec:$json.outSec, audioSec:$json.audioSec, videoSize:$json.videoSize, words:$json.words, title:TT, keyword:KW}}];
